const listCustomers = `-- name: ListCustomers :many
SELECT customer_id, name, matching_aliases, active, contact_email, contact_phone, billing_address, contact_first_name, contact_last_name, contact_phone_2, account_number, website, notes, default_currency, billing_address1, billing_address2, billing_country, billing_state, billing_city, billing_postal_code, ship_to_name, shipping_address1, shipping_address2, shipping_country, shipping_state, shipping_city, shipping_postal_code, shipping_phone, shipping_delivery_instructions, quotation_cc_emails, billing_cc_emails, default_wht_type, default_wht_rate, default_wht_gross_up, business_id FROM customers WHERE business_id=$1::uuid AND ($2::boolean IS NULL OR active = $2) ORDER BY name ASC
`

type ListCustomersParams struct {
	BusinessID pgtype.UUID
	Active     pgtype.Bool
}

func (q *Queries) ListCustomers(ctx context.Context, arg ListCustomersParams) ([]Customer, error) {
	rows, err := q.db.Query(ctx, listCustomers, arg.BusinessID, arg.Active)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []Customer
	for rows.Next() {
		var i Customer
		if err := rows.Scan(
			&i.CustomerID,
			&i.Name,
			&i.MatchingAliases,
			&i.Active,
			&i.ContactEmail,
			&i.ContactPhone,
			&i.BillingAddress,
			&i.ContactFirstName,
			&i.ContactLastName,
			&i.ContactPhone2,
			&i.AccountNumber,
			&i.Website,
			&i.Notes,
			&i.DefaultCurrency,
			&i.BillingAddress1,
			&i.BillingAddress2,
			&i.BillingCountry,
			&i.BillingState,
			&i.BillingCity,
			&i.BillingPostalCode,
			&i.ShipToName,
			&i.ShippingAddress1,
			&i.ShippingAddress2,
			&i.ShippingCountry,
			&i.ShippingState,
			&i.ShippingCity,
			&i.ShippingPostalCode,
			&i.ShippingPhone,
			&i.ShippingDeliveryInstructions,
			&i.QuotationCcEmails,
			&i.BillingCcEmails,
			&i.DefaultWhtType,
			&i.DefaultWhtRate,
			&i.DefaultWhtGrossUp,
			&i.BusinessID,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

